plan_block=r'''const YPL_AY_NO={'EYLÜL':9,'EKİM':10,'KASIM':11,'ARALIK':12,'OCAK':1,'ŞUBAT':2,'MART':3,'NİSAN':4,'MAYIS':5,'HAZİRAN':6,'TEMMUZ':7,'AĞUSTOS':8};
function planTeacherId(){const u=window.AKTIF_KULLANICI||AppStore?.get?.('session.user')||{};return u.bagliOgretmenId||u.ogretmenId||''}
function planHeadingName(id){return arr('yillikPlanBasliklari').find(x=>x.id===id)?.ad||id}
function planWeekDays(v){const m=/\((\d{1,2})-(\d{1,2})\)/.exec(v||'');return m?{start:Number(m[1]),end:Number(m[2])}:null}
function planDateRange(row,schoolYear){const month=YPL_AY_NO[String(row?.ay||'').toLocaleUpperCase('tr')],days=planWeekDays(row?.hafta),years=String(schoolYear||'').split('-').map(Number);if(!month||!days||years.length!==2||!years[0])return null;const startYear=month>=9?years[0]:years[1];let endMonth=month,endYear=startYear;if(days.end<days.start){endMonth=month===12?1:month+1;endYear=endMonth===1&&month===12?startYear+1:startYear}return{start:new Date(startYear,month-1,days.start),end:new Date(endYear,endMonth-1,days.end)}}
function planDateText(row,schoolYear){const r=planDateRange(row,schoolYear);if(!r)return row?.hafta||'';const months=['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];return r.start.getMonth()===r.end.getMonth()?`${r.start.getDate()} – ${r.end.getDate()} ${months[r.end.getMonth()]}`:`${r.start.getDate()} ${months[r.start.getMonth()]} – ${r.end.getDate()} ${months[r.end.getMonth()]}`}
function planCurrentWeekIndex(p){const rows=p?.satirlar||[];if(!rows.length)return 0;const now=new Date();now.setHours(0,0,0,0);for(let i=0;i<rows.length;i++){const r=planDateRange(rows[i],p.egitimOgretimYili);if(r&&now>=r.start&&now<=r.end)return i}for(let i=0;i<rows.length;i++){const r=planDateRange(rows[i],p.egitimOgretimYili);if(r&&r.start>=now)return i}return 0}
function planSelection(){const tid=planTeacherId();if(!tid)return null;return arr('ogretmenYillikPlanSecimleri').find(x=>x.id===tid||x.ogretmenId===tid)||null}
function planTracked(){const ids=planSelection()?.planIdler||[];return ids.map(id=>arr('yillikPlanTanimlari').find(x=>x.id===id)).filter(Boolean)}
function planTheme(p,index){const row=(p?.satirlar||[])[index]||{},vals=row.degerler||{};for(const id of p?.sutunlar||[])if(String(vals[id]||'').trim())return String(vals[id]).trim();return''}
function planNoteText(p,index){const tid=planTeacherId();if(!tid)return'';const n=arr('yillikPlanNotlari').find(x=>x.id===`${tid}_${p.id}`||(x.ogretmenId===tid&&x.planId===p.id));return String(n?.notlar?.[index]||'')}
function planDetail(p){const rows=p.satirlar||[],idx=Math.max(0,Math.min(planView.weekIndex,Math.max(0,rows.length-1))),row=rows[idx]||{},values=row.degerler||{},content=(p.sutunlar||[]).map(id=>({id,name:planHeadingName(id),value:String(values[id]||'').trim()})).filter(x=>x.value),note=planNoteText(p,idx),canNote=!!planTeacherId()&&YillikPlanService?._goruntuleyebilir?.();planView.weekIndex=idx;return{count:rows.length,html:`<section class="ka-plan-week"><div class="ka-plan-week__head"><button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-plan-back>← Planlar</button><div class="ka-plan-week__title"><strong>${esc(p.dersAdi||'Yıllık Plan')}</strong><span>${esc(p.seviye?`${p.seviye}. Sınıf`:'')}</span></div><button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-plan-current>Bu Hafta</button></div><div class="ka-plan-week__date">${esc(planDateText(row,p.egitimOgretimYili)||row.hafta||`${idx+1}. Hafta`)}</div><div class="ka-plan-week__body">${content.length?content.map(x=>`<article class="ka-plan-content-card"><span class="ka-plan-content-pill">${esc(x.name)}</span><div>${esc(x.value).replace(/\n/g,'<br>')}</div></article>`).join(''):'<div class="ka-empty">Bu hafta için içerik girilmemiş.</div>'}${note?`<article class="ka-plan-note"><strong>📝 Hafta Notum</strong><div>${esc(note).replace(/\n/g,'<br>')}</div></article>`:''}${canNote?`<button class="ka-btn ka-btn--secondary" type="button" data-plan-note>${note?'Notu Düzenle':'📝 Not Ekle'}</button>`:''}</div><div class="ka-plan-week__footer"><button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-plan-prev ${idx===0?'disabled':''}>‹ Önceki</button><span>${idx+1} / ${rows.length||0}</span><button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-plan-next ${idx>=rows.length-1?'disabled':''}>Sonraki ›</button></div></section>`}}
function plans(){const all=arr('yillikPlanTanimlari').filter(p=>match([p.dersAdi,p.seviye,p.egitimOgretimYili])).sort((a,b)=>Number(a.seviye||0)-Number(b.seviye||0)||(a.dersAdi||'').localeCompare(b.dersAdi||'','tr'));if(planView.planId){const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);if(p)return planDetail(p);planView={planId:'',weekIndex:0}}const tid=planTeacherId(),tracked=planTracked(),canEdit=YillikPlanService?._yaziYetkisiVar?.();return{count:all.length,html:`<section class="ka-stack ka-plans-page"><article class="ka-plan-hero"><div><span class="ka-plan-hero__icon">📚</span><div><h2>Yıllık Plan</h2><p>MEB ünitelendirilmiş yıllık ders planları — hafta bazlı takip</p></div></div></article><section class="ka-card"><div class="ka-card__header ka-row ka-row--between"><div><strong>🎯 Takip Ettiğim Planlar</strong><div class="ka-muted">Bugünkü haftanın içeriğine doğrudan ulaşın.</div></div>${tid?'<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-select>＋ Plan Ekle / Değiştir</button>':''}</div><div class="ka-card__body ka-stack">${!tid?'<div class="ka-empty">Profilinize bağlı bir öğretmen kaydı bulunamadı.</div>':tracked.length?tracked.map(p=>{const i=planCurrentWeekIndex(p),theme=planTheme(p,i);return`<button class="ka-plan-row" type="button" data-plan-open="${esc(p.id)}"><span><strong>${esc(p.dersAdi||'Yıllık plan')}</strong><small>${esc(p.seviye?` · ${p.seviye}. Sınıf`:'')}${theme?`<br>Bu hafta: ${esc(theme.slice(0,90))}${theme.length>90?'…':''}`:''}</small></span><span>›</span></button>`}).join(''):'<div class="ka-empty">Henüz bir plan seçmediniz. “Plan Ekle / Değiştir” ile başlayın.</div>'}</div></section>${canEdit?`<section class="ka-card"><div class="ka-card__header"><strong>⚙️ Plan Tanımları (Yönetim)</strong></div><div class="ka-card__body ka-stack">${all.length?all.map(p=>`<button class="ka-plan-row" type="button" data-plan-open="${esc(p.id)}"><span><strong>${esc(p.dersAdi||'Yıllık plan')}</strong><small>${esc([p.seviye?`${p.seviye}. Sınıf`:'',p.egitimOgretimYili,`${(p.satirlar||[]).length} hafta`,`${(p.sutunlar||[]).length} başlık`].filter(Boolean).join(' · '))}</small></span><span>›</span></button>`).join(''):'<div class="ka-empty">Yıllık plan tanımı bulunamadı.</div>'}</div></section>`:''}</section>`}}
function openPlanSelection(){const tid=planTeacherId();if(!tid)return toast?.('Profilinize bağlı bir öğretmen kaydı bulunamadı.');const plans=arr('yillikPlanTanimlari').slice().sort((a,b)=>Number(a.seviye||0)-Number(b.seviye||0)||(a.dersAdi||'').localeCompare(b.dersAdi||'','tr')),selected=new Set(planSelection()?.planIdler||[]),levels=[...new Set(plans.map(x=>x.seviye).filter(x=>x!==undefined&&x!==null&&x!==''))];const body=`<p class="ka-muted">Takip etmek istediğiniz planları seçin. Seçimler cihazda hemen güncellenir ve arka planda senkronize edilir.</p><div class="ka-plan-picker">${levels.map(level=>`<section><strong>${esc(level)}. Sınıf</strong>${plans.filter(x=>String(x.seviye)===String(level)).map(p=>`<label class="ka-check ka-plan-picker__row"><input type="checkbox" data-plan-choice value="${esc(p.id)}" ${selected.has(p.id)?'checked':''}><span><b>${esc(p.dersAdi||'Yıllık plan')}</b><small>${esc(p.egitimOgretimYili||'')} · ${(p.satirlar||[]).length} hafta</small></span></label>`).join('')}</section>`).join('')||'<div class="ka-empty">Henüz plan tanımı yok.</div>'}</div>`,ov=modal('🎯 Plan Ekle / Değiştir',body);ov.querySelector('[data-save]').onclick=async()=>{const ids=[...ov.querySelectorAll('[data-plan-choice]:checked')].map(x=>x.value);try{await YillikPlanService.secimKaydet(tid,ids);ov.remove();toast?.('Yıllık plan seçimleri kaydedildi.')}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Plan seçimleri kaydedilemedi.')}}}
function openPlanNote(){const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId),tid=planTeacherId();if(!p||!tid)return;const existing=planNoteText(p,planView.weekIndex),ov=modal('📝 Hafta Notu',`<label class="ka-field"><span class="ka-field__label">Bu haftayla ilgili notunuz</span><textarea data-plan-note-text rows="5" placeholder="Materyal, hazırlık veya hatırlatma notu…">${esc(existing)}</textarea></label>`);ov.querySelector('[data-save]').onclick=async()=>{try{await YillikPlanService.notKaydet(tid,p.id,planView.weekIndex,ov.querySelector('[data-plan-note-text]').value.trim());ov.remove();toast?.('Hafta notu kaydedildi.')}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Not kaydedilemedi.')}}}
function bindPlans(out){if(!out)return;out.querySelectorAll('[data-plan-open]').forEach(b=>b.addEventListener('click',()=>{const p=arr('yillikPlanTanimlari').find(x=>x.id===b.dataset.planOpen);if(!p)return;planView={planId:p.id,weekIndex:planCurrentWeekIndex(p)};render()}));out.querySelector('[data-plan-back]')?.addEventListener('click',()=>{planView={planId:'',weekIndex:0};render()});out.querySelector('[data-plan-select]')?.addEventListener('click',openPlanSelection);out.querySelector('[data-plan-note]')?.addEventListener('click',openPlanNote);out.querySelector('[data-plan-current]')?.addEventListener('click',()=>{const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);if(p){planView.weekIndex=planCurrentWeekIndex(p);render()}});out.querySelector('[data-plan-prev]')?.addEventListener('click',()=>{planView.weekIndex=Math.max(0,planView.weekIndex-1);render()});out.querySelector('[data-plan-next]')?.addEventListener('click',()=>{const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);planView.weekIndex=Math.min(Math.max(0,(p?.satirlar||[]).length-1),planView.weekIndex+1);render()})}
function calendar(){'''
